SELECT CASE WHEN LOWER(v.Venue_Name) LIKE '%supersport park%' AND LOWER(c.City_Name) LIKE '%centurion%' THEN 'Yes' ELSE 'No' END AS Is_SuperSport_Park_In_Centurion
